const body = $('Webhook registreren').first().json.body || {};
const existing = $input.first().json || {};
const dup = !!(existing && existing.email);
function rnd(){ return Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2); }
const salt = rnd();
const session_id = 'u_' + Date.now().toString(36) + '_' + rnd().slice(0,6);
const token = rnd() + rnd();
return [{ json: {
  duplicate: dup,
  email: String(body.email || '').toLowerCase().trim(),
  password: String(body.password || ''),
  salt: salt,
  session_id: session_id,
  token: token
} }];

const row = $input.first().json || {};
const ok = !!(row.email && row.password_hash && row.check_hash && row.password_hash === row.check_hash);
if(!ok) return [{ json: { ok: false, error: 'invalid', message: 'E-mailadres of wachtwoord onjuist.' } }];
return [{ json: {
  ok: true,
  token: row.session_token,
  session_id: row.session_id,
  name: row.name || '',
  onboarding_complete: (row.onboarding_complete === true || row.onboarding_complete === 'true')
} }];

const user = $('Gebruiker via token (me)').first().json || {};
if(!user.session_id){ return [{ json: { ok: false, error: 'auth' } }]; }
const logs = $input.all().map(function(i){ return i.json; }).filter(function(l){ return l && l.session_id === user.session_id; });
const today = new Date().toISOString().slice(0,10);
const todayLogs = logs.filter(function(l){ return (l.log_date || '') === today; });
return [{ json: {
  ok: true,
  profile: {
    name: user.name || '', age: user.age || '', weight: user.weight || '', address: user.address || '',
    language: user.language || 'Nederlands',
    medications: user.medications || '', wake_time: user.wake_time || '', sleep_time: user.sleep_time || '',
    reminders_per_day: user.reminders_per_day || 2,
    contact1_name: user.contact1_name || '', contact1_relationship: user.contact1_relationship || '', contact1_contact: user.contact1_contact || '',
    contact2_name: user.contact2_name || '', contact2_relationship: user.contact2_relationship || '', contact2_contact: user.contact2_contact || '',
    gp_name: user.gp_name || '', gp_practice: user.gp_practice || '', gp_contact: user.gp_contact || '',
    consent_store: user.consent_store, consent_gp: user.consent_gp,
    onboarding_complete: (user.onboarding_complete === true || user.onboarding_complete === 'true')
  },
  checkins: todayLogs,
  recent: logs.slice(-20)
} }];

const user = $('Gebruiker via token (profiel)').first().json || {};
if(!user.session_id){ return [{ json: { ok: false, error: 'auth', message: 'Uw sessie is verlopen. Log opnieuw in.' } }]; }
return [{ json: { ok: true, message: 'Uw gegevens zijn opgeslagen.' } }];

const user = $('Gebruiker via token (check-in)').first().json || {};
const body = $('Webhook check-in').first().json.body || {};
if(!user.session_id){ return [{ json: { ok: false } }]; }
const now = new Date();
const period = body.period || 'ochtend';
const wb = (body.wellbeing !== undefined && body.wellbeing !== null && body.wellbeing !== '') ? String(body.wellbeing) : '';
const med = body.medication_taken ? String(body.medication_taken) : '';
const text = String(body.text || '').trim();
const score = parseInt(wb, 10);
let aiRaw = '';
try { const ai = $('AI gezondheidscheck').first().json || {}; aiRaw = ai.content || ai.text || ai.output || ai.response || (ai.message && ai.message.content) || ''; if (typeof aiRaw !== 'string') { aiRaw = JSON.stringify(aiRaw); } } catch (e) { aiRaw = ''; }
const aiUp = String(aiRaw).toUpperCase();
let aiLevel = 'NORMAAL';
if (text) { if (aiUp.indexOf('URGENT') > -1) { aiLevel = 'URGENT'; } else if (aiUp.indexOf('AANDACHT') > -1 || aiUp.indexOf('ATTENTION') > -1) { aiLevel = 'AANDACHT'; } }
const low = text.toLowerCase();
const urg = ['pijn op de borst','benauwd','ademnood','geen adem','niet ademen','gevallen','beroerte','flauwgevallen','bloed','hartkloppingen'];
for (const w of urg) { if (low.indexOf(w) > -1) { aiLevel = 'URGENT'; break; } }
let concern = 'NORMAAL';
if (!isNaN(score) && score <= 2) { concern = 'AANDACHT'; }
if (med === 'nee') { concern = 'AANDACHT'; }
if (aiLevel === 'AANDACHT') { concern = 'AANDACHT'; }
if (aiLevel === 'URGENT') { concern = 'URGENT'; }
return [{ json: { ok: true, session_id: user.session_id, log_date: now.toISOString().slice(0,10), log_time: now.toISOString().slice(11,16), period: period, wellbeing: wb, medication_taken: med, symptoms: text, possible_concern: '', concern_level: concern, urgency: (concern === 'URGENT') ? 'hoog' : ((concern === 'AANDACHT') ? 'midden' : 'laag'), follow_up_needed: (concern === 'NORMAAL') ? 'nee' : 'ja', ai_summary: aiRaw ? ('AI: ' + String(aiRaw)).slice(0,200) : '' } }];

const user = $('Gebruiker via token (hulp)').first().json || {};
const body = $('Webhook hulp').first().json.body || {};
if(!user.session_id){ return [{ json: { ok: false } }]; }
const to = [];
if(user.contact1_contact){ to.push(String(user.contact1_contact).trim()); }
if(user.contact2_contact){ to.push(String(user.contact2_contact).trim()); }
const gpOk = (user.consent_gp === true || user.consent_gp === 'true');
if(gpOk && user.gp_contact && String(user.gp_contact).indexOf('@') > -1){ to.push(String(user.gp_contact).trim()); }
const now = new Date();
return [{ json: {
  ok: true,
  session_id: user.session_id,
  event_type: 'HELP',
  event_time: now.toISOString(),
  detail: body.message || 'Gebruiker heeft om hulp gevraagd via de website.',
  notified_contact: to.join(', '),
  to_list: to.join(','),
  has_contacts: to.length > 0,
  resolved: false,
  contact_name: user.contact1_name || '',
  user_name: user.name || '',
  user_address: user.address || '',
  user_language: user.language || 'Nederlands'
} }];

const p = $('Hulp voorbereiden').first().json;
const msg = p.has_contacts
  ? 'Uw contactpersonen zijn gewaarschuwd. Is er direct gevaar? Bel zelf 112.'
  : 'Uw hulpverzoek is genoteerd, maar er is nog geen contactpersoon ingesteld. Is er direct gevaar? Bel zelf 112.';
return [{ json: { ok: true, message: msg } }];

